(() => {
 'use strict';
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=MGTU_escape;
 let draft=structuredClone(MGTU_content()),data={programs:[],facts:[]},view='page',dirty=false,previewMode='desktop';
 const labels={page:['Страница','Всё на своих местах.','Меняйте содержание блоков и смотрите, как выглядит страница.'],programs:['Направления','Направления под контролем.','Редактируйте программы, места, квоты, экзамены и сроки обучения.'],design:['Оформление','Характер вашего университета.','Настройте фирменные цвета и шрифт без правки кода.'],applications:['Заявки','От интереса — к встрече.','Будущий раздел для работы с регистрациями на мероприятие.']};
 const texts={...MGTU_DEFAULTS.texts,discoverTitle:'Сначала\nпознакомься.\nПотом решай.',discoverDescription:'Выбирать своё будущее проще,\nкогда можешь увидеть его вблизи.',faqTitle:'Давай\nразберёмся.',finalTitle:'Увидимся\nв МГТУ.'};
 const input=(label,key,value,options={})=>`<label>${esc(label)}${options.textarea?`<textarea data-field="${key}" rows="${options.rows||3}">${esc(value)}</textarea>`:`<input data-field="${key}" type="${options.type||'text'}" value="${esc(value)}" ${options.maxlength?'maxlength="'+options.maxlength+'"':''}>`}${options.hint?`<small>${esc(options.hint)}</small>`:''}</label>`;
 const textInput=(label,key)=>input(label,'texts.'+key,draft.texts?.[key]??texts[key],{textarea:true});
 const toggle=(label,key,value)=>`<label class="toggle-field">${esc(label)}<input type="checkbox" data-field="${key}" ${value?'checked':''}></label>`;
 const block=(n,title,body,open=false)=>`<details ${open?'open':''}><summary><span>${n}</span><b>${esc(title)}</b><span>⌄</span></summary><div class="editor-fields">${body}</div></details>`;
 function setDirty(value=true){dirty=value;$('#draftState').textContent=dirty?'Есть несохранённые изменения':'Все изменения сохранены';$('#draftState').style.color=dirty?'#9a7729':'';}
 function render(){const info=labels[view];$('#viewBreadcrumb').textContent=info[0];$('#viewTitle').textContent=info[1];$('#viewDescription').textContent=info[2];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  if(view==='page')$('#editorPanel').innerHTML=
   block('01','Первый экран',input('Главный заголовок','title',draft.title,{textarea:true,hint:'Переносы строк сохранятся на сайте.'})+input('Описание','description',draft.description,{textarea:true})+input('Дата и время','date',draft.date)+input('Место проведения','place',draft.place),true)+
   block('02','Об университете',toggle('Показывать блок','sections.about',draft.sections.about)+textInput('Заголовок','aboutTitle')+input('Сведения об университете','factsText',(draft.facts||data.facts).join('\n'),{textarea:true,rows:10,hint:'Один пункт на строку. Сведения распределены по вкладкам на главной. Сохраняйте порядок исходных пунктов.'}))+
   block('03','Знакомство с МГТУ',toggle('Показывать блок','sections.discover',draft.sections.discover)+textInput('Заголовок','discoverTitle'))+
   block('04','Каталог программ',toggle('Показывать блок','sections.programs',draft.sections.programs)+textInput('Заголовок','programsTitle')+'<small>Карточки программ редактируются в разделе «Направления».</small>')+
   block('05','Памятки и вопросы',toggle('Показывать памятки','sections.resources',draft.sections.resources)+textInput('Заголовок памяток','resourcesTitle')+toggle('Показывать вопросы','sections.faq',draft.sections.faq)+textInput('Заголовок вопросов','faqTitle'))+
   block('06','Финальный экран и контакты',textInput('Финальный заголовок','finalTitle')+input('Телефон приёмной комиссии','phone',draft.phone)+input('Электронная почта','email',draft.email,{type:'email'}))+
   '<p class="save-note">Это прототип: настройки действуют только в текущем браузере. Авторизация, серверное хранение, загрузка файлов и публикация войдут в рабочую админку.</p>';
  if(view==='programs'){$('#editorPanel').innerHTML='<input class="admin-search" id="adminSearch" type="search" aria-label="Поиск программ в редакторе" placeholder="Найти программу или факультет"><p class="program-editor-count">'+data.programs.length+' программ из исходного каталога</p><div id="adminPrograms"></div>';renderProgramList('');$('#adminSearch').addEventListener('input',e=>renderProgramList(e.target.value));}
  if(view==='design')$('#editorPanel').innerHTML='<div class="editor-card"><span class="admin-badge">МГТУ / ПАЛИТРА 02</span><h2>Один вуз. Разные характеры.</h2><p>Основная концепция — глубокий синий, холодный голубой и лавандовый. Направления используют тематические палитры.</p><div class="editor-fields">'+color('Светлый акцент','accent',draft.accent)+color('Голубой акцент','secondary',draft.secondary)+color('Основной тёмный','background',draft.background)+'</div></div><div class="editor-card"><h2>Палитры направлений</h2><p>Нажмите палитру, чтобы попробовать её как основную тему макета. Цвета карточек направлений сохранят свою принадлежность.</p><div class="palette-library">'+Object.entries(MGTU_PALETTES).map(([key,p])=>'<button class="palette-option" data-palette="'+key+'"><span>'+esc(p.name)+'</span><span>'+p.colors.map(c=>'<i style="--swatch:'+c+'" title="'+c+'"></i>').join('')+'</span></button>').join('')+'</div><p class="editor-palette-note">Янтарный #FFB020 сохранён в фирменной палитре как вариант для обсуждения.</p></div><div class="editor-card"><h2>Типографика</h2><div class="font-specimen">Steppe.<br>День открытых дверей в МГТУ.</div><p>Подключены пять начертаний Steppe: Regular, Medium, SemiBold, Bold и ExtraBold. Файлы находятся в самом макете.</p><div class="editor-fields">'+input('Семейство шрифта','font',draft.font,{hint:'Steppe уже подключён. Для другого шрифта понадобится его файл.'})+'</div></div><div class="editor-card"><h2>Логотип</h2><img src="assets/crest.png" alt="Логотип МГТУ" style="height:90px;width:120px;object-fit:contain;margin:20px 0"><p>Официальный герб МГТУ связывает бордовый с общей палитрой. Замена файла будет доступна в рабочей админке.</p></div>';
  if(view==='applications')$('#editorPanel').innerHTML='<div class="editor-card empty-apps"><span></span><h2>Здесь будут заявки.</h2><p>Сейчас форма работает как демонстрация. Контактные данные не сохраняются и не отправляются.</p></div><div class="editor-card"><h2>Как будет работать регистрация</h2><div class="flow-step"><b>1</b><span>Гость заполняет форму на сайте</span></div><div class="flow-step"><b>2</b><span>Заявка появляется в защищённой админке</span></div><div class="flow-step"><b>3</b><span>Ответственный получает уведомление</span></div><p style="margin-top:20px">Для подключения нужны место хранения заявок, получатель уведомлений и утверждённые условия обработки персональных данных.</p></div>';
 }
 function color(label,key,value){return `<label>${esc(label)}<div class="color-row"><input type="color" data-color="${key}" value="${esc(value)}" aria-label="${esc(label)}: выбор цвета"><input type="text" data-field="${key}" value="${esc(value)}" pattern="#[0-9a-fA-F]{6}" maxlength="7" aria-label="${esc(label)}: HEX"></div></label>`;}
 function editableProgram(id){
  const original=data.programs.find(p=>p.id===id);if(!original)return null;
  const patch=draft.programs[id]||{};
  draft.programs[id]={...structuredClone(original),...patch,admission:{...structuredClone(original.admission||{}),...patch.admission}};
  return draft.programs[id];
 }
 function admissionTable(id,a){return `<div class="admission-editor"><h4>Места, формы обучения и квоты</h4><p>Меняйте каждую ячейку. Тире означает отсутствие мест.</p>${input('Заголовки столбцов','programs.'+id+'.admission.columnsText',(a.headers||[]).join('\n'),{textarea:true,rows:3,hint:'Один столбец на строку. Можно добавить профиль или подразделение.'})}<div class="admin-table-scroll"><table class="admin-admission-table"><thead><tr>${(a.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}<th></th></tr></thead><tbody>${(a.rows||[]).map((row,r)=>`<tr>${(a.headers||[]).map((h,c)=>`<td><input aria-label="${esc(h)}: строка ${r+1}" data-field="programs.${id}.admission.rows.${r}.${c}" value="${esc(row[c]||'')}"></td>`).join('')}<td><button class="remove-admission-row" data-remove-row="${r}" data-program="${id}" aria-label="Удалить строку ${r+1}">×</button></td></tr>`).join('')}</tbody></table></div><button class="admin-row-button" data-add-row="${id}">+ Добавить строку</button></div>`;}
 function renderProgramList(query){const list=data.programs.filter(p=>{const s={...p,...draft.programs[p.id]};return(s.name+' '+s.faculty).toLowerCase().includes(query.trim().toLowerCase());});$('#adminPrograms').innerHTML=list.map(p=>{const s={...p,...draft.programs[p.id]},a=s.admission||{},key='programs.'+p.id+'.';return `<details class="program-editor-row" data-editor-program="${p.id}"><summary><span>${esc(s.name)}<br><small>${esc(s.level)}${a.code?' · '+esc(a.code):''}</small></span><span>⌄</span></summary><div class="editor-fields">${input('Название',key+'name',s.name)}${input('Факультет',key+'faculty',s.faculty)}<label>Уровень образования<select data-field="${key}level">${['Бакалавриат','Специалитет','Магистратура'].map(level=>`<option ${s.level===level?'selected':''}>${level}</option>`).join('')}</select></label>${toggle('Показывать на сайте',key+'visible',s.visible!==false)}${input('Код направления',key+'admission.code',a.code||'')}${input('Учебный год',key+'admission.year',a.year||'')}${input('Профиль / специализация',key+'admission.profile',a.profile||'',{textarea:true})}${input('Статус набора',key+'admission.status',a.status||'',{textarea:true,hint:'Оставьте пустым при обычном наборе.'})}${admissionTable(p.id,a)}${input('ЕГЭ: предметы и минимальные баллы',key+'admission.ege',a.ege||'',{textarea:true,rows:5})}${input('Вступительные испытания после СПО',key+'admission.spo',a.spo||'',{textarea:true,rows:5})}${input('Вступительное испытание в магистратуру',key+'admission.entrance',a.entrance||'',{textarea:true})}${input('Сроки обучения',key+'admission.duration',a.duration||'',{textarea:true})}${input('Дополнительная информация',key+'admission.notes',a.notes||'',{textarea:true})}${input('Ссылка на описание программы',key+'document',s.document||'',{type:'url'})}${input('Ссылка на стоимость',key+'cost',s.cost||'',{type:'url'})}<button class="admin-row-button" data-reset-program="${p.id}">Восстановить исходные данные направления</button></div></details>`;}).join('')||'<div class="editor-card"><p>Ничего не найдено. Попробуйте другое слово.</p></div>';}
 function refreshProgramEditor(id){const query=$('#adminSearch')?.value||'';renderProgramList(query);const row=$(`[data-editor-program="${id}"]`);if(row)row.open=true;}
 $('#editorPanel').addEventListener('click',e=>{
  const add=e.target.closest('[data-add-row]'),remove=e.target.closest('[data-remove-row]'),reset=e.target.closest('[data-reset-program]');
  if(add){const id=add.dataset.addRow,p=editableProgram(id);if(!p.admission.headers?.length)p.admission.headers=['Форма обучения','Бюджет','Отдельная квота','Особая квота','По договору'];p.admission.rows??=[];p.admission.rows.push(p.admission.headers.map(()=>''));setDirty();refreshProgramEditor(id);}
  if(remove){const id=remove.dataset.program,p=editableProgram(id);p.admission.rows.splice(Number(remove.dataset.removeRow),1);setDirty();refreshProgramEditor(id);}
  if(reset){const id=reset.dataset.resetProgram;delete draft.programs[id];setDirty();refreshProgramEditor(id);}
 });
 $('#editorPanel').addEventListener('change',e=>{if(!e.target.dataset.field?.endsWith('.columnsText'))return;const id=e.target.dataset.field.split('.')[1],p=editableProgram(id);p.admission.headers=e.target.value.split('\n').map(x=>x.trim()).filter(Boolean);p.admission.rows=(p.admission.rows||[]).map(row=>p.admission.headers.map((_,i)=>row[i]||''));delete p.admission.columnsText;setDirty();refreshProgramEditor(id);});
 $('#editorPanel').addEventListener('input',e=>{const key=e.target.dataset.field||e.target.dataset.color;if(!key)return;if(key.startsWith('programs.'))editableProgram(key.split('.')[1]);let value=e.target.type==='checkbox'?e.target.checked:e.target.value;if(key==='factsText')draft.facts=value.split('\n').map(s=>s.trim()).filter(Boolean);else{const bits=key.split('.');let target=draft;for(const part of bits.slice(0,-1)){target[part]??={};target=target[part];}target[bits.at(-1)]=value;}if(e.target.dataset.color){$(`[data-field="${key}"]`).value=value;}if(['accent','secondary','background'].includes(key)&&/^#[0-9a-fA-F]{6}$/.test(value)){const picker=$(`[data-color="${key}"]`);if(picker)picker.value=value;}setDirty();});
 function notify(message){$('#adminToast').textContent=message;$('#adminToast').classList.add('visible');setTimeout(()=>$('#adminToast').classList.remove('visible'),3500);}
 $('#saveDraft').addEventListener('click',()=>{if(!draft.title.trim())return notify('Добавьте заголовок.');for(const key of ['accent','secondary','background'])if(!/^#[0-9a-fA-F]{6}$/.test(draft[key]))return notify('Укажите цвета в формате #RRGGBB.');for(const p of Object.values(draft.programs)){for(const key of ['document','cost'])if(p[key]&&!/^https?:\/\//i.test(p[key]))return notify('Ссылки программ должны начинаться с https:// или http://.');}if(draft.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(draft.email))return notify('Проверьте адрес электронной почты.');if(!MGTU_write('mgtu-content',draft))return notify('Не удалось сохранить настройки в браузере.');setDirty(false);$('#sitePreview').src='index.html';notify('Макет обновлён. Изменения сохранены в этом браузере.');});
 $('#resetDraft').addEventListener('click',()=>{draft=structuredClone(MGTU_content());setDirty(false);render();notify('Несохранённые изменения отменены.');});
 $('#editorPanel').addEventListener('click',e=>{const button=e.target.closest('[data-palette]');if(!button)return;const palette=MGTU_PALETTES[button.dataset.palette];if(!palette)return;draft.background=palette.colors[0];draft.accent=button.dataset.palette==='brand'?'#f7f7f7':palette.colors[Math.min(3,palette.colors.length-1)];draft.secondary=button.dataset.palette==='brand'?'#a7c7ff':palette.colors[palette.colors.length-1];draft.brandVersion=2;setDirty();render();notify('Палитра выбрана. Сохраните изменения для предпросмотра.');});
 $$('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();}));
 function resizePreview(){const viewport=$('#previewViewport');const iframe=$('#sitePreview');const width=viewport.clientWidth;const source=previewMode==='mobile'?390:1280;const scale=Math.min(width/source,1);viewport.classList.toggle('mobile',previewMode==='mobile');iframe.style.width=source+'px';iframe.style.transform=`scale(${scale})`;iframe.style.height=Math.ceil(viewport.clientHeight/scale)+'px';}
 $$('[data-preview]').forEach(b=>b.addEventListener('click',()=>{previewMode=b.dataset.preview;$$('[data-preview]').forEach(x=>x.classList.toggle('active',x===b));$('#previewViewport').classList.toggle('mobile',previewMode==='mobile');resizePreview();}));
 new ResizeObserver(resizePreview).observe($('#previewViewport'));window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 fetch('data.json').then(r=>r.text()).then(text=>{data=JSON.parse(text.replace(/^\uFEFF/,''));$('#adminProgramCount').textContent=data.programs.length;render();}).catch(()=>{render();notify('Не удалось загрузить каталог. Перезагрузите страницу.');});render();resizePreview();
})();
